INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8c50-79ba-ad59-2e502c606165'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'Two exchange rates are given: 1 USD = SGD x in 2023, and in 2022 the rate was SGD 0.030 less per USD. The difference in exchanging SGD 10 000 between the two years is USD 166. Write down the equation in x.', '10000/x - 10000/(x - 0.030) = 166', 'In 2023, 10 000 SGD gives 10000/x USD. In 2022, 10 000 SGD gives 10000/(x - 0.030) USD. Their difference is 166 USD, so 10000/x - 10000/(x - 0.030) = 166.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.624Z'::timestamptz, '2026-08-15T07:36:12.624Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8c78-7f7a-8cd5-4ec7c331a4f1'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'Show that (7n - 1)^2 - (n - 1)^2 is a multiple of 12 for all integer values of n.', '12n(4n - 1)', 'Use the difference of two squares: (7n - 1)^2 - (n - 1)^2 = [(7n - 1) + (n - 1)] [(7n - 1) - (n - 1)] = (8n - 2)(6n). This simplifies to 12n(4n - 1), which is always divisible by 12.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.664Z'::timestamptz, '2026-08-15T07:36:12.664Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b6b5-78bc-9d44-95b008df431a'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Explain why x^2 - 10x + 7 has its minimum value when x = 5.', 'Because the squared term is smallest when x = 5.', 'From x^2 - 10x + 7 = (x - 5)^2 - 18, the squared term (x - 5)^2 is always at least 0. It is smallest when x = 5, so the whole expression is minimum at x = 5.', 'Easy', '{"tags":"algebra,quadratics,minimum-value","subtopic":"quadratic expressions","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.845Z'::timestamptz, '2026-07-26T12:42:25.845Z'::timestamptz) ON CONFLICT (id) DO NOTHING;